T[1275]={"^Spell critical strike chance increased by (.-)%%%. Spell haste increased by (.-)%%%.%s*$","La probabilidad de golpe crítico con hechizos aumenta un {{1}}%. La celeridad de hechizos aumenta un {{2}}%."}
