T[1287]={"^Generating (.-) Rage every (.-) sec%.\n\nCost of spells and abilities reduced by (.-)%%%.%s*$","Genera {{1}} de Furia cada {{2}} s.\n\nEl coste de los hechizos y habilidades se reduce un {{3}}%."}
T[1288]={"^Curing (.-) poison effects every (.-)%.%s*$","Cura los efectos de veneno {{1}} cada {{2}}."}
