T[1523]={"^Imprisoned!%s*$","¡Prisionero!"}
T[1524]={"^Increases your critical damage by (.-)%% and all offensive critical strikes now generate 5 |cffcc99ffStatic|r%.%s*$","Aumenta tu daño crítico en {{1}}% y todos tus golpes críticos ofensivos generan 5 |cffcc99ffEstático|r."}
T[1525]={"^Immune to poison, disease and curse effects%.%s*$","Inmune a los efectos de veneno, enfermedad y maldición."}
T[1526]={"^Dispelling (.-) disease and poison effect every (.-) sec%.%s*$","Disipa el efecto de enfermedad y veneno de {{1}} cada {{2}} seg."}
T[1527]={"^Movement speed increased by (.-)%%%. Critical strike chance increased by (.-)%%%.%s*$","Velocidad de movimiento aumentada en {{1}}%. Posibilidad de golpe crítico aumentada en {{2}}%."}
T[1528]={"^Movement speed increased by (.-)%%%.%s*$","Velocidad de movimiento aumentada en {{1}}%."}
