T[1544]={"^Healing for (.-)%% of all damage dealt%.%s*$","Sanación equivalente al {{1}}% de todo el daño infligido."}
T[1545]={"^|cffffffffClaw Sweep|r now spreads |cffffffffInfected Claw|r from affected targets to another random enemy within (.-)yd%.%s*$","|cffffffffBarrido de garras|r ahora propaga |cffffffffGarra infectada|r desde los objetivos afectados a otro enemigo aleatorio en un radio de {{1}}yd."}
T[1546]={"^Maximum health increased by (.-)%%%.%s*$","Salud máxima aumentada en {{1}}%."}
T[1547]={"^Movement speed increased by (.-)%%%. Immune to slows%. Able to walk on water%.%s*$","La velocidad de movimiento aumenta un {{1}}%. Inmune a los efectos de ralentización. Capaz de caminar sobre el agua."}
T[1548]={"^Immune to fear, charm, and horrify effects%.%s*$","Inmune a los efectos de temor, encanto y horrorizar."}
