T[1558]={"^Threat generation increased by (.-)%%%.\n\nDamage taken reduced by (.-)%%%. Damage dealt reduced by (.-)%%%.%s*$","La generación de amenaza aumenta un {{1}}%.\n\nEl daño recibido se reduce un {{2}}%. El daño infligido se reduce un {{3}}%."}
T[1559]={"^Increases threat generation by (.-)%% and permanently activates Demon Form during combat%.\n\nReduces damage dealt by (.-)%%%.%s*$","Aumenta la generación de amenaza en {{1}}% y activa permanentemente la Forma Demoníaca durante el combate.\n\nReduce el daño infligido en {{2}}%."}
T[1560]={"^Increases threat generation by (.-)%%%.\n\nReduces damage dealt by (.-)%%%.%s*$","Aumenta la generación de amenaza en {{1}}%.\n\nReduce el daño infligido en {{2}}%."}
