T[1888]={"^Interrupted%.Counters the enemy's spellcast, preventing any spell from that school of magic from being cast for (.-)%.%s*$","Interrumpido. Contrarresta el lanzamiento de hechizos del enemigo, evitando que se lance cualquier hechizo de esa escuela de magia durante {{1}}."}
T[1889]={"^Ending this spell's channel will heal all nearby allies based on the amount of time you spend channeling%.%s*$","Terminar el canalizado de este hechizo sanará a todos los aliados cercanos según la cantidad de tiempo que pases canalizando."}
T[1890]={"^While below 50%% mana, your healing done is increased by (.-)%%%. \n\nWhile above 50%% mana your critical strike chance is increased by (.-)%%%.%s*$","Mientras tu maná sea inferior al 50%, tu sanación realizada se incrementa en {{1}}%.\n\nMientras tu maná supere el 50%, tu probabilidad de golpe crítico aumentará en {{2}}%."}
T[1891]={"^Causes your |cFFFFFFFFRipple|r to perform a unique effect based on your active |cFFFFFFFFAeon|r:%s*$","Hace que tu |cFFFFFFFFOndulación|r realice un efecto único basado en tu |cFFFFFFFFAeon|r activo:"}
T[1892]={"^|cffffffffAeon|r spells grant you (.-)%% increased damage and healing for (.-), stacking (.-) times%.%s*$","Los hechizos de |cffffffffAeon|r te otorgan un {{1}}% de aumento de daño y sanación durante {{2}}, acumulándose {{3}} veces."}
T[1893]={"^Movement speed slowed by (.-)%%%. After (.-), enemies standing in the area are blasted for (.-) Nature damage and they are rooted for (.-)%.%s*$","La velocidad de movimiento se reduce en un {{1}}%. Tras {{2}}, los enemigos que se encuentren en el área recibirán {{3}} de daño de Naturaleza y quedarán inmovilizados durante {{2}}."}
T[1894]={"^Immune to all damage%. Pacified and silenced%. Movement speed reduced by (.-)%%%.%s*$","Inmune a todo el daño. Pacificado y silenciado. La velocidad de movimiento se reduce en un {{1}}%."}
T[1895]={"^Taking (.-) Chromatic Damage every (.-) sec%.%s*$","Recibes {{1}} de daño cromático cada {{2}} s."}
T[1896]={"^Absorbing damage taken%.%s*$","Absorbe el daño recibido."}
T[1897]={"^Magic Damage done increased by (.-)%%%.%s*$","El daño de magia infligido aumenta un {{1}}%."}
T[1898]={"^Increases the range of your Necromancer Diseases by (.-) yd and their Duration by (.-)%%%.%s*$","Aumenta el alcance de tus enfermedades de Nigromante en {{1}} yd y su duración en un {{2}}%."}
T[1899]={"^When your Crypt Plague effect deals damage, you gain (.-)%% increased Spell Haste for (.-) sec%.%s*$","Cuando el efecto de tu Peste de la cripta inflija daño, ganarás un {{1}}% de aumento de celeridad de hechizos durante {{2}} s."}
T[1900]={"^While active, you generate 3 Focus every (.-) sec%.%s*$","Mientras esté activo, generas 3 Enfoque cada {{1}} seg."}
T[1901]={"^Magic Damage increased by (.-)%%%. You do not suffer any pushback from taking damage while casting%.%s*$","El daño de magia aumenta un {{1}}%. No sufres ningún retroceso al recibir daño mientras lanzas hechizos."}
T[1902]={"^For (.-), |cffffffffQuick Shots|r generate an additional |cffffffffArchery Point|r and |cffffffffSkullpiercer Shot|r%$%?s806345%[ and |cffffffffWoodland Arrow|r%]%[ deal (.-)%% increased damage%.\n\nFor the duration, |cffffffffSkullpiercer Shots|r%$%?s806345%[ and |cffffffffWoodland Arrow|r%]%[ used with 5 |cffffffffArchery Points|r will summon 1 |cffffffffWar Falcon|r%.%s*$","Durante {{1}}, |cffffffffDisparos Rápidos|r generan un punto adicional de |cffffffffArquería|r y |cffffffffFlecha Desgarradora|r$?s806345[ y las |cffffffffFlechas Boscosas|r][ causan un daño aumentado en {{2}}%.\n\nDurante todo el tiempo, |cffffffffFlechas Desgarradoras|r$?s806345[ y las |cffffffffFlechas Boscosas|r][ usadas con 5 |cffffffffpuntos de Arquería|r invocarán 1 |cffffffffHalcones de Guerra|r."}
T[1903]={"^Deals damage after the duration ends%.%s*$","Inflige daño al finalizar la duración."}
T[1904]={"^Immune to grip and knockback effects%.%s*$","Inmune a los efectos de agarre y de retroceso."}
T[1905]={"^Allows the Exsanguination effect from your Shadowfang Shield to stack up to (.-) additional times%.%s*$","Permite que el efecto de Exanguinación de tu Escudo de Colmillo Sombrío acumule hasta {{1}} veces adicionales."}
T[1906]={"^|cffffffffRadiant Flame|r now restores (.-)%% maximum mana and deals (.-)%% more damage%.%s*$","|cffffffffLlama radiante|r ahora restaura el {{1}}% del maná máximo y inflige un {{2}}% más de daño."}
T[1907]={"^Your next spell with a Supercharged effect consumes this effect to perform the effect%.%s*$","Tu próximo hechizo con efecto de Sobrecarga consume este efecto para realizar su efecto."}
