T[5848]={"^Attack speed increased by (.-)%%%.\nSpell Cooldowns reduced by (.-)%%%.%s*$","La velocidad de ataque aumenta un {{1}}%.\nLos tiempos de reutilización de los hechizos se reducen un {{2}}%."}
