T[5889]={"^Enraged%.\n\nDamage increased by (.-)%%\nAttack speed increased by (.-)%%%.%s*$","Enfurecido.\n\nDaño aumentado un {{1}}%\nVelocidad de ataque aumentada un {{2}}%."}
