T[8224]={"^Shielded against both physical and magical damage%.\n\nHalf of the damage absorbed is reflected back onto a random raid member as Shadowflame damage%.%s*$","Protege contra el daño físico y mágico.\n\nLa mitad del daño absorbido se refleja en un miembro aleatorio de la banda como daño de Llama Sombría."}
T[8225]={"^Baths nearby allies in Flames%.\n\nDealing (.-) Fire damage when attacked%.%s*$","Baña a los aliados cercanos en llamas.\n\nInflige {{1}} de daño de Fuego al recibir un ataque."}
T[8226]={"^(.-) Frost damage taken every (.-) second%.\nMovement speed reduced by (.-)%%%.%s*$","{{1}} de daño de Escarcha recibido cada {{2}} segundo.\nLa velocidad de movimiento se reduce un {{3}}%."}
T[8227]={"^(.-) Nature damage inflicted every (.-) sec%.\n\nAll stats reduced by (.-)%%%.%s*$","{{1}} de daño de Naturaleza infligido cada {{2}} s.\n\nTodas las estadísticas se reducen un {{3}}%."}
T[8228]={"^Increases the casters spell damage by 40%%%.%s*$","Aumenta el daño con hechizos del lanzador en 40%."}
T[8229]={"^Burns enemies for (.-) Fire damage every second%.%s*$","Quema a los enemigos con {{1}} de daño de Fuego cada segundo."}
T[8230]={"^Shadow damage taken increased by (.-)%%%.\nMovement speed reduced by (.-)%%%.%s*$","El daño de Sombras recibido aumenta un {{1}}%.\nLa velocidad de movimiento se reduce un {{2}}%."}
