T[10585]={"^Magical Damage taken increased by 10%%%.Movement speed slowed by 10%%%.%s*$","Daño mágico recibido aumentado en 10% . Velocidad de movimiento ralentizada en 10%."}
T[10586]={"^Taking (.-) Arcane Damage every 3 seconds%. Movement speed slowed by (.-)%%%.%s*$","Recibes {{1}} Daño Arcano cada 3 segundos. Velocidad de movimiento ralentizada en {{2}}%."}
