T[10658]={"^Stunned%.%s*$","Aturdido."}
T[10659]={"^Critical damage increased by (.-)%%%. Fire resistance increased by (.-)%.%s*$","El daño crítico aumenta un {{1}}%. La resistencia al fuego aumenta un {{2}}."}
T[10660]={"^Restoring (.-) mana every 5 seconds%. Costs reduced by (.-)%%%.%s*$","Restaura {{1}} maná cada 5 segundos. Costos reducidos en {{2}}%."}
