T[11050]={"^|cffffffffThaumaturgy|r refunds 1 |cffffffffInscribed Rune|r and deals (.-)%% increased damage%.%s*$","|cffffffffTaumaturgia|r reembolsa 1 |cffffffffRuna Inscripción|r y inflige {{1}}% más daño."}
T[11051]={"^Your Thaumatury ability deals (.-)%% reduced damage but regenerates (.-)%% of your Maximum Mana%.%s*$","Tu habilidad de Taumaturgia inflige un {{1}}% menos de daño, pero regenera un {{2}}% de tu maná máximo."}
T[11052]={"^Your Thaumaturgy deals (.-)%% bonus damage%.%s*$","Tu Taumaturgia inflige un {{1}}% de daño adicional."}
T[11053]={"^Your Thaumaturgy ability deals (.-)%% reduced damage but increases your Arcane Spell Power by (.-)%% of your Intellect for (.-)%.%s*$","Tu habilidad de Taumaturgia inflige un {{1}}% menos de daño, pero aumenta tu poder con hechizos de Arcano en un {{2}}% de tu intelecto durante {{3}}."}
T[11054]={"^Your Solar Power session cannot decay until you leave combat%.\n\nThis effect is gained when you reach 50 Solar Power%.%s*$","Tu sesión de Energía Solar no puede desgastarse hasta que abandonas el combate.\n\nEste efecto se obtiene cuando alcanzas 50 Energía Solar."}
T[11055]={"^Your next spell is empowered!\n\nIllumination: Critical strike chance increased%.\n\nShine: Affects all nearby allies, and heals for an increased amount%.\n\nSunshine: Ticks twice as fast for half the duration and costs no Mana%.%s*$","¡Tu próximo hechizo está potenciado!\n\nIluminación: la probabilidad de golpe crítico aumenta.\n\nBrillo: afecta a todos los aliados cercanos y sana una cantidad mayor.\n\nLuz solar: los efectos se activan el doble de rápido durante la mitad de la duración y no cuesta maná."}
T[11056]={"^Your next spell is empowered!\n\nIllumination: Is instant and costs no Mana%.\n\nShine: Heals for an increased amount%.\n\nSunshine: Ticks twice as fast for half the duration and costs no Mana%.%s*$","¡Tu próximo hechizo está potenciado!\n\nIluminación: es instantáneo y no cuesta maná.\n\nBrillo: sana una cantidad mayor.\n\nLuz solar: los efectos se activan el doble de rápido durante la mitad de la duración y no cuesta maná."}
T[11057]={"^Your next spell is empowered!\n\nIllumination: Is instant and costs no Mana%.\n\nShine: Affects all nearby allies, and heals for an increased amount%.\n\nSunshine: Ticks twice as fast for half the duration and costs no Mana%.%s*$","¡Tu próximo hechizo está potenciado!\n\nIluminación: es instantáneo y no cuesta maná.\n\nBrillo: afecta a todos los aliados cercanos y sana una cantidad mayor.\n\nLuz solar: los efectos se activan el doble de rápido durante la mitad de la duración y no cuesta maná."}
T[11058]={"^Spell Power increased by (.-)%% of your Intellect%.%s*$","El poder con hechizos aumenta un {{1}}% de tu intelecto."}
T[11059]={"^Your next Primordial Blast unleashes a Shard of Conflagration for each stack of this effect%. Stacks up to 3 times%.\n\nShards of Conflagration deal Fire Damage, plus bonus Fire Damage for each consecutive Shard of Conflagration that hits the target%.%s*$","Tu próximo Explosión primigenia libera un Fragmento de Conflagración por cada acumulación de este efecto. Se acumula hasta 3 veces.\n\nLos Fragmentos de Conflagración causan Daño de Fuego, más daño adicional de Fuego para cada Fragmento consecutivo que golpee al objetivo."}
T[11060]={"^Your next Primordial Blast unleashes a Shard of Ice for each stack of this effect%. Stacks up to 3 times%.\n\nEach Shard causes Frost Damage and applies a stacking slow%.%s*$","Tu próximo Explosión primigenia libera un Fragmento de Escarcha por cada acumulación de este efecto. Se acumula hasta 3 veces.\n\nCada Fragmento causa Daño de Escarcha y aplica una ralentización en pila."}
T[11061]={"^Your next Primordial Blast unleashes a Shard of Arcana for each stack of this effect%. Stacks up to 3 times%.\n\nShards of Arcana deal Arcane Damage, and restore a portion of your Maximum Mana%.%s*$","Tu próximo Explosión Primigenia libera un Fragmento de Arcana por cada acumulación de este efecto. Se acumula hasta 3 veces.\n\nLos Fragmentos de Arcana causan daño Arcano y restauran una parte de tu Maná Máximo."}
