T[13019]={"^Special attacks restore (.-) energy to the pet's owner%.%s*$","Los ataques especiales restauran {{1}} de energía al dueño de la mascota."}
T[13020]={"^Physical damage done reduced by (.-)%%%. Holy damage done increased by (.-)%%%.%s*$","El daño físico realizado se reduce en un {{1}}%. El daño sagrado realizado aumenta un {{2}}%."}
T[13021]={"^Deals (.-) Shadowstrike damage every 2 seconds%.%s*$","Inflige {{1}} daño Escarcha cada 2 segundos."}
T[13022]={"^Your next Mind Blast or Vampiric Touch is instant, has increased critical strike chance by (.-)%% and grants 2 combo points%.%s*$","Tu próximo Golpe Mental o Tocar Vampírico es instantáneo, aumenta la probabilidad de golpe crítico en {{1}}% y concede 2 puntos de combate."}
T[13023]={"^Increases the damage of your next Mind Flay by (.-)%% %((.-)%% versus players%) or your next Mind Sear by (.-)%% and reduces their cast times by (.-)%%%.%s*$","Aumenta el daño de tu próximo Flaqueo mental en un {{1}}% ({{2}}% frente a jugadores) o el de tu próximo Flaqueo mentalmente en un {{3}}% y reduce sus tiempos de lanzamiento en un {{4}}%."}
T[13024]={"^Increases the damage done by Unstable Affliction by (.-)%%, and Curse of Agony by (.-)%%%. Each tick consumes one charge%.%s*$","Incrementa el daño infligido por Aflicción inestable en un {{1}}% y el de Maldición de agonía en un {{2}}%. Cada tic consume una carga."}
T[13025]={"^Your bleeds deal (.-)%% increased damage%. Eviscerate and Dispatch deal (.-)%% increased%.%s*$","Tus hemorragias infligen un {{1}}% más de daño. Eviscerar y Despachar infligen un {{2}}% más."}
T[13026]={"^Increases your critical damage bonus by 20%%%.%s*$","Aumenta tu bonificación de daño por golpe crítico en 20%."}
T[13027]={"^Increases all rage costs by (.-)%% and lower warrior global cooldowns by (.-)%%%.%s*$","Aumenta todos los costes de rabia en un {{1}}% y reduce el tiempo de reutilización global de guerrero en un {{2}}%."}
T[13028]={"^Increases your Rage costs by (.-)%%, lowers your global cooldowns of Warrior abilities by (.-)%% per stack %(cannot go lower than 1 sec%)%.%s*$","Aumenta tus costos de ira en {{1}}%, reduce el tiempo de reutilización global de las habilidades del Guerrero en {{2}}% por acumulación (no puede reducirse a menos que 1 seg)."}
T[13029]={"^Your next Raging Blow costs no rage%.%s*$","Tu próximo Golpe de furia no cuesta furia."}
