T[13091]={"^Healing (.-) over (.-)%.%s*$","Sana {{1}} durante {{2}}."}
T[13092]={"^Rage generation from damage dealt increased by (.-)%%%.\nCritical strike chance of all abilities increased by (.-)%%%.%s*$","La generación de rabia por el daño infligido aumenta un {{1}}%.\nLa probabilidad de golpe crítico de todas las habilidades aumenta un {{2}}%."}
T[13093]={"^ignite removal%s*$","eliminación de ignición"}
T[13094]={"^Stagger an additional (.-)%% of damage taken%.%s*$","Tambaleo un {{1}}% adicional del daño recibido."}
