T[13097]={"^Increases the frost damage you deal by (.-)%% %((.-)%% against players%) for 8 seconds%.%s*$","Aumenta el daño de Escarcha que infliges en {{1}}% ({{2}}% contra jugadores) durante 8 segundos."}
T[13098]={"^(.-) Plague damage every (.-) seconds%.\n\nPhysical damage taken from the caster increased by (.-)%%%.%s*$","{{1}} de daño de la Peste cada {{2}} segundos.\n\ndan el daño físico recibido del lanzador aumenta un {{3}}%."}
T[13099]={"^Your Fireball and Pyroblast critical strikes will grant (.-)%% spell haste for (.-)%.%s*$","Tus golpes críticos con Bola de fuego y Piroclasma te otorgarán un {{1}}% de celeridad de hechizo durante {{2}}."}
T[13100]={"^Chance to trigger your next Molten Core increased by (.-)%%%.%s*$","La probabilidad de activar tu próximo Núcleo fundido aumenta un {{1}}%."}
T[13101]={"^Casting damaging spells will increase the chance to trigger Fingers of Frost by (.-)%% until it triggers%.%s*$","Lanzar hechizos de daño aumentará la probabilidad de activar Dedos de escarcha en un {{1}}% hasta que se active."}
T[13102]={"^The cooldown of your next Swiftmend is reduced by 1%.5 sec per stack%.%s*$","El tiempo de reutilización de tu próximo Swiftmend se reduce en 1.5 seg por acumulación."}
