T[13289]={"^|cffFF9900Strength, Agility, Stamina, Spirit and Intellect|r increased by |cffFF9900(.-)%%|r for |cffFF9900(.-)|r%.%s*$","|cffFF9900La fuerza, la agilidad, el aguante, el espíritu y el intelecto|r aumentan un |cffFF9900{{1}}%|r durante |cffFF9900{{2}}|r."}
