T[13510]={"^Attack speed increased by (.-)%%%.\nCasting speed increased by (.-)%%%.\nMovement speed increased by (.-)%%%.%s*$","Velocidad de ataque aumentada en un {{1}}%.\nVelocidad de lanzamiento aumentada en un {{2}}%.\nVelocidad de movimiento aumentada en un {{3}}%."}
