T[13620]={"^(.-)%% less chance to hit%.\n(.-)%% slower attacks%.\n(.-)%% increase damage taken from the physical school%s*$","{{1}}% menos de probabilidad de acertar.\n{{2}}% de ataques más lentos.\n{{3}}% de aumento del daño recibido de la escuela física"}
T[13621]={"^Health reduced to 1%.\nHealing effects reduced by (.-)%%%.\nHealth regeneration reduced by (.-)%%%.%s*$","La salud se reduce a 1.\nLos efectos de sanación se reducen un {{1}}%.\nLa regeneración de salud se reduce un {{2}}%."}
T[13622]={"^You feel a bit hazy%.%.%.\nStamina reduced by (.-)%.\nSpirit increased by (.-)%.%s*$","Te sientes un poco aturdido...\nEl aguante se reduce en {{1}}.\nEl espíritu aumenta en {{2}}."}
T[13623]={"^Calls forth a guardian of time to assist you inside the Black Morass for up to (.-)%.%s*$","Invoca a un guardián del tiempo para que te ayude dentro de la Ciénaga Negra durante hasta {{1}}."}
