T[13625]={"^The cast time of your next Holy Light or Prayer of Healing spell is reduced by (.-) sec and increases spell haste and Holy damage by (.-)%%%. %.%s*$","El tiempo de lanzamiento de tu próximo hechizo de Luz sagrada o Oración de sanación se reduce en {{1}} seg y aumenta la celeridad de hechizos y el daño sagrado en un {{2}}%. ."}
T[13626]={"^The cast time of your next Holy Light or Prayer of Healing spell is reduced by (.-) sec  and your spell haste and Holy damage is increased by 4%%%.%s*$","El tiempo de lanzamiento de tu próximo hechizo de Luz sagrada o Oración de sanación se reduce en {{1}} seg  y tu celeridad de hechizos y daño sagrado aumentan un 4%."}
T[13627]={"^The cast time of your next Holy Light or Prayer of Healing spell is reduced by (.-) sec %.%s*$","El tiempo de lanzamiento de tu próximo hechizo de Luz sagrada o Oración de sanación se reduce en {{1}} seg ."}
T[13628]={"^Mana cost of all spells reduced by (.-)%%%.\nCritical effect chance of Holy healing spells increased by 20%%%.%s*$","El coste de maná de todos los hechizos se reduce un {{1}}%.\nLa probabilidad de efecto crítico de los hechizos de sanación sagrada aumenta un 20%."}
T[13629]={"^Taking 10%% increased damage from the caster's Seal spells%.%s*$","Recibes un 10% más de daño de los hechizos de Sello del lanzador."}
T[13630]={"^Damage taken of the next attack received reduced by (.-)%%%.%s*$","El daño recibido del próximo ataque recibido se reduce un {{1}}%."}
T[13631]={"^(.-)%% increased chance to be crit%.\n(.-) reduced attack power%.\n(.-)%% increased bleed damage%.%s*$","{{1}}% de aumento de la probabilidad de golpe crítico.\n{{2}} de reducción de poder de ataque.\n{{3}}% de aumento del daño por hemorragia."}
T[13632]={"^Shadow damage inflicted over (.-)%.%s*$","Daño de sombras infligido durante {{1}}."}
T[13633]={"^Attack power increased by (.-)%. %(Battle Shout%)\nAttack power increased by (.-)%%%. %(Unleashed Rage%)%s*$","El poder de ataque aumenta en {{1}}. (Grito de batalla)\nEl poder de ataque aumenta en un {{2}}%. (Furia desatada)"}
T[13634]={"^You are Victorious!%s*$","¡Eres victorioso!"}
T[13635]={"^Allows the use of Victory Rush!%s*$","¡Permite usar Carga de victoria!"}
