T[15514]={"^Disabled%.\n\nPut to sleep%.\n\nDamage taken removes this effect%.%s*$","Desactivado.\n\nPuesto a dormir.\n\nEl daño recibido elimina este efecto."}
T[15515]={"^Movement speed reduced by (.-)%%%.\n\n(.-) Frost damage inflicted every second%.%s*$","La velocidad de movimiento se reduce un {{1}}%.\n\n{{2}} de daño de Escarcha infligido cada segundo."}
