T[18370]={"^Critical Strike Damage increased by (.-)%%%.%s*$","El daño de golpe crítico aumenta un {{1}}%."}
T[18371]={"^Taking (.-) chaos damage every 2 seconds%.\nDamage taken from the caster increased by (.-)%%%.%s*$","Recibes {{1}} de daño de caos cada 2 segundos.\nEl daño recibido del lanzador aumenta un {{2}}%."}
T[18372]={"^Reduces damage dealt to players by 5%%%.%s*$","Reduce el daño infligido a los jugadores en un 5%."}
T[18373]={"^Critical strike rating increased by (.-)%% of spirit%.%s*$","El índice de golpe crítico aumenta un {{1}}% de tu espíritu."}
T[18374]={"^Taking (.-) nature damage every 4 seconds%.\nDamage taken increased by (.-)%% from the caster%.%s*$","Recibes {{1}} de daño de naturaleza cada 4 segundos.\nEl daño recibido aumenta un {{2}}% por parte del lanzador."}
