T[21277]={"^Permanently enchant a melee weapon for your spell, ranged and melee attacks to increase your Attack Power by (.-) and your Spell Power by (.-) for (.-)%.  This can not occur more than once every 220%.5 sec%.%s*$","Encanta permanentemente un arma cuerpo a cuerpo para que tus ataques con hechizos, a distancia y cuerpo a cuerpo aumenten tu poder de ataque en {{1}} y tu poder con hechizos en {{2}} durante {{3}}. Esto no puede ocurrir más de una vez cada 220.5 seg."}
T[21278]={"^Permanently enchant a melee weapon for your spell, ranged and melee attacks to increase your Attack Power by (.-) and your Spell Power by (.-) for (.-)%.  This can not occur more than once every 22%.5 seconds%.%s*$","Encanta permanentemente un arma cuerpo a cuerpo para que tus ataques con hechizos, a distancia y cuerpo a cuerpo aumenten tu poder de ataque en {{1}} y tu poder con hechizos en {{2}} durante {{3}}. Esto no puede ocurrir más de una vez cada 22.5 segundos."}
T[21279]={"^Permanently enchant a melee weapon for your spell, ranged and melee attacks to increase your Attack Power by (.-) and your Spell Power by (.-) for (.-)%. This can not occur more than once every 22%.5 seconds%.%s*$","Encanta permanentemente un arma cuerpo a cuerpo para que tus ataques con hechizos, a distancia y cuerpo a cuerpo aumenten tu poder de ataque en {{1}} y tu poder con hechizos en {{2}} durante {{3}}. Esto no puede ocurrir más de una vez cada 22.5 segundos."}
T[21280]={"^Permanently enchant a melee weapon for your spell, ranged and melee attacks have a chance to increase your Armor Penetration rating by (.-) for (.-)%. This can not occur more than once every 20 seconds%.%s*$","Encanta permanentemente un arma cuerpo a cuerpo para que tus ataques con hechizos, a distancia y cuerpo a cuerpo tengan una probabilidad de aumentar tu índice de penetración de armadura en {{1}} durante {{2}}. Esto no puede ocurrir más de una vez cada 20 segundos."}
T[21281]={"^Permanently enchant a weapon to have a chance to increase your intellect by (.-) while additionally restoring 12%% of your base mana for (.-) when you cast spells or deal melee damage%. This can not occur more than once every 220%.5 sec%.%s*$","Encanta permanentemente un arma para que tenga una probabilidad de aumentar tu intelecto en {{1}} y, además, restaurar un 12% de tu maná base durante {{2}} cuando lances hechizos o inflijas daño cuerpo a cuerpo. Esto no puede ocurrir más de una vez cada 220.5 s."}
T[21282]={"^Permanently enchant a weapon to have a chance to increase your intellect by (.-) while additionally restoring 12%% of your base mana for (.-) when you cast spells or deal melee damage%. This can not occur more than once every 22%.5 seconds%.%s*$","Encanta permanentemente un arma para que tenga una probabilidad de aumentar tu intelecto en {{1}} y, además, restaurar un 12% de tu maná base durante {{2}} cuando lances hechizos o inflijas daño cuerpo a cuerpo. Esto no puede ocurrir más de una vez cada 22.5 segundos."}
T[21283]={"^Permanently enchant a melee weapon to have a chance to regenerate 20 energy over (.-) and increase your Agility by (.-) for (.-) when dealing melee damage%. This can not occur more than once every 25 seconds%.%s*$","Encanta permanentemente un arma cuerpo a cuerpo para que tenga una probabilidad de regenerar 20 de energía durante {{1}} y aumentar tu agilidad en {{2}} durante {{1}} al infligir daño cuerpo a cuerpo. Esto no puede ocurrir más de una vez cada 25 segundos."}
T[21284]={"^Permanently enchant a weapon to grant your spell casts, ranged and melee attacks a chance to increase your spirit by (.-) while additionally restoring 12%% of your base mana over (.-)%. This can not occur more than once every 220%.5 sec%.%s*$","Encanta permanentemente un arma para que tus lanzamientos de hechizos, ataques a distancia y cuerpo a cuerpo tengan una probabilidad de aumentar tu espíritu en {{1}} y, además, restaurar un 12% de tu maná base durante {{2}}. Esto no puede ocurrir más de una vez cada 220.5 seg."}
T[21285]={"^Permanently enchant a weapon to grant your spell casts, ranged and melee attacks a chance to increase your spirit by (.-) while additionally restoring 12%% of your base mana over (.-)%. This can not occur more than once every 22%.5 seconds%.%s*$","Encanta permanentemente un arma para que tus lanzamientos de hechizos, ataques a distancia y cuerpo a cuerpo tengan una probabilidad de aumentar tu espíritu en {{1}} y, además, restaurar un 12% de tu maná base durante {{2}}. Esto no puede ocurrir más de una vez cada 22.5 segundos."}
T[21286]={"^Permanently enchant a weapon to grant your elemental spell casts, ranged and melee attacks a chance to increase your spirit by (.-) while additionally restoring 12%% of your base mana over (.-)%. This can not occur more than once every 22%.5 seconds%.%s*$","Encanta permanentemente un arma para que tus lanzamientos de hechizos elementales, ataques a distancia y cuerpo a cuerpo tengan una probabilidad de aumentar tu espíritu en {{1}} y, además, restaurar un 12% de tu maná base durante {{2}}. Esto no puede ocurrir más de una vez cada 22.5 segundos."}
T[21287]={"^Permanently enchant a melee weapon to make your spell & melee attacks have a chance to reduce the cost of your next two abilities by 50%%%. This can not occur more than once every 20 seconds%.%s*$","Encanta permanentemente un arma cuerpo a cuerpo para que tus ataques de hechizos y cuerpo a cuerpo tengan una probabilidad de reducir el coste de tus dos próximas habilidades en un 50%. Esto no puede ocurrir más de una vez cada 20 segundos."}
